import sysimport discordfrom discord import Colorfrom discord.ext import commandsfrom print_color import printfrom utils.EmbedGeneratorUtil import EmbedGeneratorclass ShutdownCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.is_owner()    @commands.command(name="shutdown", help="This command shuts down the bot. Can only be ran by bot owner.")    async def shutdown(self, ctx: discord.ext.commands.Context, *, reason: str = "No Specific Reason Provided"):        """        Shuts the bot down safely.        :param reason: If there is a specific reason for the bot shutdown.        :param ctx: This is the discord Interaction we can access data from        :return:        """        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description=f"Shutting down.\n{reason}", colour=Color.magenta())        await ctx.reply(embed=embed, mention_author=False, ephemeral=True)        print(f"Shutting Down. - {reason}", tag="IN PROGRESS", tag_color="yellow", color="white")        for vc in self.bot.voice_clients:            await vc.disconnect()        await self.bot.close()async def setup(bot: commands.Bot):    await bot.add_cog(ShutdownCommand(bot))